async function readLocalScore(number) {
  if (number < 0) throw new RangeError("negative score");
  return number * 2;
}

const outcomes = await Promise.allSettled([3, -1, 4].map(readLocalScore));
for (const item of outcomes) {
  if (item.status === "fulfilled") console.log(item.value);
  else console.log("skipped: " + item.reason.message);
}

import assert from "node:assert/strict";

function minutes(value) {
  if (!Number.isInteger(value) || value < 0) {
    throw new RangeError("expected a nonnegative integer");
  }
  return value;
}

assert.equal(minutes(0), 0);
assert.throws(() => minutes(-1), RangeError);
console.log("2 checks passed");
